<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\ClientIdentity\Infrastructure\Driver;

use Psr\Container\ContainerInterface;
use Override;
use Slim\Routing\RouteCollectorProxy;
use Civi\Lughauth\Features\Access\ClientIdentity\Infrastructure\Driver\Rest\ClientIdentityAllowController;
use Civi\Lughauth\Features\Access\ClientIdentity\Infrastructure\Driver\Rest\ClientIdentityListController;
use Civi\Lughauth\Features\Access\ClientIdentity\Infrastructure\Driver\Rest\ClientIdentityCreateController;
use Civi\Lughauth\Features\Access\ClientIdentity\Infrastructure\Driver\Rest\ClientIdentityRetrieveController;
use Civi\Lughauth\Features\Access\ClientIdentity\Infrastructure\Driver\Rest\ClientIdentityUpdateController;
use Civi\Lughauth\Features\Access\ClientIdentity\Infrastructure\Driver\Rest\ClientIdentityDeleteController;
use Civi\Lughauth\Shared\Security\Rbac\Handler;
use Civi\Lughauth\Shared\Infrastructure\MicroPlugin;
use Civi\Lughauth\Shared\Security\SecurityPlugin;
use Civi\Lughauth\Shared\Infrastructure\StartupProcessor;
use Civi\Lughauth\Shared\Event\EventListenersRegistrarInterface;
use Civi\Lughauth\Features\Access\ClientIdentity\Application\Service\Visibility\ClientIdentityRestrictFilterToVisibility;
use Civi\Lughauth\Features\Access\ClientIdentity\Application\Policy\Filter\TenantAccesible;
use Civi\Lughauth\Features\Access\ClientIdentity\Application\Policy\Allow\Create\IsAuthenticatedCreateAllow;
use Civi\Lughauth\Features\Access\ClientIdentity\Application\Usecase\Create\ClientIdentityCreateAllowDecision;
use Civi\Lughauth\Features\Access\ClientIdentity\Application\Policy\Allow\Update\IsAuthenticatedUpdateAllow;
use Civi\Lughauth\Features\Access\ClientIdentity\Application\Usecase\Update\ClientIdentityUpdateAllowDecision;
use Civi\Lughauth\Features\Access\ClientIdentity\Application\Policy\Allow\Retrieve\IsAuthenticatedRetrieveAllow;
use Civi\Lughauth\Features\Access\ClientIdentity\Application\Usecase\Retrieve\ClientIdentityRetrieveAllowDecision;
use Civi\Lughauth\Features\Access\ClientIdentity\Application\Policy\Allow\List\IsAuthenticatedListAllow;
use Civi\Lughauth\Features\Access\ClientIdentity\Application\Usecase\List\ClientIdentityListAllowDecision;
use Civi\Lughauth\Features\Access\ClientIdentity\Application\Policy\Allow\Delete\IsAuthenticatedDeleteAllow;
use Civi\Lughauth\Features\Access\ClientIdentity\Application\Usecase\Delete\ClientIdentityDeleteAllowDecision;
use Civi\Lughauth\Features\Access\ClientIdentity\Infrastructure\Driven\ClientIdentityReadRepositoryAdapter;
use Civi\Lughauth\Features\Access\ClientIdentity\Infrastructure\Driven\ClientIdentityWriteRepositoryAdapter;
use Civi\Lughauth\Features\Access\ClientIdentity\Domain\Gateway\ClientIdentityReadGateway;
use Civi\Lughauth\Features\Access\ClientIdentity\Domain\Gateway\ClientIdentityWriteGateway;

class ClientIdentityPlugin extends MicroPlugin
{
    #[Override]
    public function registerServiceDefinition(array $def): array
    {
        $def[ClientIdentityReadGateway::class] = \DI\autowire(ClientIdentityReadRepositoryAdapter::class);
        $def[ClientIdentityWriteGateway::class] = \DI\autowire(ClientIdentityWriteRepositoryAdapter::class);
        return $def;
    }
    #[Override]
    public function registerRoutes(RouteCollectorProxy $collector): void
    {
        $collector->group('/api/access/client-identity', [$this, 'setRoutesForClientIdentity']);
        $collector->group('/api/me/acl/access/client-identity', [$this, 'setRoutesForClientIdentityAcl']);
    }
    #[Override]
    public function registerEvents(EventListenersRegistrarInterface $listener): void
    {
        $listener->registerListener(ClientIdentityRestrictFilterToVisibility::class, TenantAccesible::class);
        $listener->registerListener(ClientIdentityCreateAllowDecision::class, IsAuthenticatedCreateAllow::class);
        $listener->registerListener(ClientIdentityUpdateAllowDecision::class, IsAuthenticatedUpdateAllow::class);
        $listener->registerListener(ClientIdentityRetrieveAllowDecision::class, IsAuthenticatedRetrieveAllow::class);
        $listener->registerListener(ClientIdentityListAllowDecision::class, IsAuthenticatedListAllow::class);
        $listener->registerListener(ClientIdentityDeleteAllowDecision::class, IsAuthenticatedDeleteAllow::class);
    }
    #[Override]
    public function registerStartup(StartupProcessor $processor): void
    {
        $processor->register(function (ContainerInterface $container) {
            $handler = $container->get(Handler::class);
            $handler->registerResourceAction("client-identity", "list", "READ");
            $handler->registerResourceAction("client-identity", "create", "WRITE");
            $handler->registerResourceAction("client-identity", "retrieve", "READ");
            $handler->registerResourceAction("client-identity", "update", "WRITE");
            $handler->registerResourceAction("client-identity", "delete", "WRITE");

            $handler->registerResourceAttribute("client-identity", "user", "MANAGE");
            $handler->registerResourceAttribute("client-identity", "relyingParty", "MANAGE");
            $handler->registerResourceAttribute("client-identity", "trustedClient", "MANAGE");
            $handler->registerResourceAttribute("client-identity", "roles", "MANAGE");
            $handler->registerResourceAttribute("client-identity", "version", "MANAGE");
        }, StartupProcessor::before(SecurityPlugin::STARTUP_ORDER));
    }
    public function setRoutesForClientIdentityAcl(RouteCollectorProxy $clientIdentityGroup): void
    {
        $clientIdentityGroup->get('', [ClientIdentityAllowController::class, 'genericAllow']);
        $clientIdentityGroup->get('/{uid}', [ClientIdentityAllowController::class, 'contextualAllow']);
    }
    public function setRoutesForClientIdentity(RouteCollectorProxy $clientIdentityGroup): void
    {
        $clientIdentityGroup->get('', [ClientIdentityListController::class, 'list']);
        $clientIdentityGroup->post('', [ClientIdentityCreateController::class, 'create']);
        $clientIdentityGroup->get('/{uid}', [ClientIdentityRetrieveController::class, 'retrieve']);
        $clientIdentityGroup->put('/{uid}', [ClientIdentityUpdateController::class, 'update']);
        $clientIdentityGroup->delete('/{uid}', [ClientIdentityDeleteController::class, 'delete']);
        $clientIdentityGroup->delete('', [ClientIdentityDeleteController::class, 'deleteAllForQuery']);
        $clientIdentityGroup->get('/~/delete-status/{uid}', [ClientIdentityDeleteController::class, 'checkDeleteAllForQueryStatus']);
    }
}
